from dataclasses import dataclass
from typing import Optional

class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    @dataclass
    class Ticket:
        id: int
        customer: str
        vip: bool
        title: str
        priority: str
        closed: bool = False

    def __init__(self) -> None:
        self.tickets = []
        self.customer_vip = {}
        self.next_ticket_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self.customer_vip[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")

        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        ticket_id = self.next_ticket_id
        self.next_ticket_id += 1

        vip = self.customer_vip.get(customer, False)
        ticket = self.Ticket(ticket_id, customer, vip, title, priority)
        self.tickets.append(ticket)

        self.tickets.sort(key=self._sort_key)

        return ticket_id

    def next_ticket(self) -> Optional[int]:
        if not self.tickets:
            return None

        next_ticket = self.tickets.pop(0)
        return next_ticket.id

    def close(self, ticket_id: int) -> None:
        for ticket in self.tickets:
            if ticket.id == ticket_id:
                ticket.closed = True
                return

    def reopen(self, ticket_id: int) -> None:
        for ticket in self.tickets:
            if ticket.id == ticket_id:
                if ticket.closed:
                    raise ValueError("Cannot reopen a closed ticket")
                else:
                    return

    def _sort_key(self, ticket: Ticket) -> tuple:
        if ticket.vip:
            vip_sort = 0
        else:
            vip_sort = 1

        priority_sort = self.PRIORITIES.index(ticket.priority)

        return (vip_sort, priority_sort)

# Example usage:
if __name__ == "__main__":
    helpdesk = Helpdesk()

    helpdesk.add_customer("John Doe", vip=True)
    helpdesk.add_customer("Jane Doe")

    ticket1_id = helpdesk.open_ticket("John Doe", "VIP ticket", priority="normal")
    ticket2_id = helpdesk.open_ticket("Jane Doe", "Normal ticket", priority="normal")
    ticket3_id = helpdesk.open_ticket("Jane Doe", "High priority ticket", priority="high")
    ticket4_id = helpdesk.open_ticket("Jane Doe", "Critical ticket", priority="critical")

    print(helpdesk.next_ticket())  # Should print ticket1_id
    print(helpdesk.next_ticket())  # Should print ticket4_id
    print(helpdesk.next_ticket())  # Should print ticket3_id
    print(helpdesk.next_ticket())  # Should print ticket2_id

    helpdesk.close(ticket1_id)
    try:
        helpdesk.reopen(ticket1_id)
    except ValueError as e:
        print(e)  # Should print "Cannot reopen a closed ticket"
